{
  "headline": "Carvedilol is not on FDA's shortage list; Corvale General has 19.5 days on hand and the rule‑ranked alternate is Advagen Pharma Limited",
  "headline_cites": ["D2", "D1", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include carvedilol as of 2026-10-21.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale General holds 283 tablets of carvedilol 25 mg, which at 14.5 tablets per day provides 19.5 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "The rule‑ranked first alternate manufacturer is Advagen Pharma Limited, which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D3"]
    },
    {
      "text": "A second alternate is Advagen Pharma Ltd., also not on the shortage list and with no plant identified on its label.",
      "cites": ["D4"]
    },
    {
      "text": "A third alternate is Aurobindo Pharma Limited, likewise not on the shortage list and with no plant identified on its label.",
      "cites": ["D5"]
    },
    {
      "text": "The current label for carvedilol 25 mg (NDC 71335247403) names Bryant Ranch Prepack as the registered plant (FEI 1000519407) with a VAI inspection on 2026-07-16.",
      "cites": ["E13"]
    },
    {
      "text": "FDA inspection records for that plant show an OAI classification in 2009 and a series of VAI inspections through 2026, with the most recent VAI known date of 2026-10-14.",
      "cites": ["E3", "E11"]
    }
  ]
}
